  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+r2*0.4)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const noise=Math.sin(Math.sin(sx*0.07+t*0.2)*2.3+Math.sin(sy*0.09-t*0.3)*1.7+t*0.5)*0.12;
  const blend=reaction*0.65+cell*0.18+r2*0.1+noise*0.07;
  const v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,50,85],[15,95,115],[25,155,145],[80,195,120],[180,195,70],[220,175,50],[215,115,55],[195,70,80],[145,40,90],[70,25,85],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.2:1.0;
  const glow=Math.max(0,reaction*0.15);
  return[Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*255)|0),Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*200)|0),Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*150)|0)];
}
